-- Parroquia - Pasionistas, con diseño propio: el templo dibujado junto al texto
-- de entrada, el horario vivo (la próxima misa y el despacho, calculados al
-- momento), el mapa con la dirección al lado, los Pasionistas con su signo
-- sobre fondo oscuro y la cronología en cinta.
--
-- Solo se sustituye la página que sigue con el horario de antes (el bloque de
-- datos en cuadrícula): si alguien ya la ha editado en el CMS, se queda como está.

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Parroquia - Pasionistas","subtitulo":"Santa María Goretti, nuestra sede canónica, y la comunidad pasionista que la atiende.","foto":"","fotoAlt":""},"bloques":[{"tipo":"dibujo","titulo":"Santa María Goretti","presentacion":{"ladoDibujo":"derecha"},"dibujo":"templo","html":"<p>El Grupo Parroquial tiene su sede canónica en la <strong>Parroquia de Santa María Goretti</strong>, en la calle Corregidor Paz Guzmán, en el distrito de Cruz de Humilladero. Es una parroquia de barrio, de unos diez mil vecinos, y desde que se fundó la atiende una comunidad de <strong>Padres Pasionistas</strong>.</p><p>Su templo, del arquitecto Verdú, se terminó en 1981: una estructura triangular sin columnas, con forma de concha y lucernas circulares. En él celebramos nuestros cultos y en él se reúne el Grupo durante el año.</p>"},{"tipo":"horario","titulo":"Horarios y despacho","misas":[{"etiqueta":"Lunes a sábado","dias":[1,2,3,4,5,6],"horas":["09:30","19:00"],"horasVerano":["09:30","20:00"]},{"etiqueta":"Domingos y festivos","dias":[0],"horas":["10:00","12:00"],"horasVerano":[]}],"despacho":[{"dias":[2,5],"desde":"18:00","hasta":"20:00"}],"verano":{"desde":"07-01","hasta":"08-31"},"lineas":[{"etiqueta":"Confesiones","valor":"Antes de cada misa"},{"etiqueta":"Teléfono","valor":"952 331 203"},{"etiqueta":"Correo","valor":"goretti@diocesismalaga.es"}]},{"tipo":"mapa","titulo":"Cómo llegar","presentacion":{"alto":"medio","estilo":"oscuro","disposicion":"lado"},"lugar":"Parroquia de Santa María Goretti","direccion":"C. Corregidor Paz Guzmán, 13, 29006 Málaga","indicaciones":"En el barrio, en el distrito de Cruz de Humilladero."},{"tipo":"dibujo","titulo":"Los Pasionistas","presentacion":{"fondo":"oscuro","ladoDibujo":"izquierda"},"dibujo":"signoPasionista","html":"<p>La Congregación de la Pasión de Jesucristo, cuyos religiosos firman con las siglas C.P., la fundó <strong>San Pablo de la Cruz</strong> en Italia, en el siglo XVIII. Su carisma es mantener viva la memoria de la Pasión de Cristo y anunciarla, sobre todo a quienes sufren.</p><p>Llegaron a Málaga en 1972, cuando el obispado erigió esta parroquia y se la encomendó. Desde entonces ha sido una comunidad abierta y volcada con los jóvenes, y su trabajo ha salido de la parroquia: capellanías de colegios y del cementerio, el Teléfono de la Esperanza, ejercicios espirituales y acompañamiento espiritual.</p><p>En el barrio sostienen Cáritas parroquial y el hogar del jubilado, la catequesis de niños, jóvenes y adultos, la preparación de bautizos y bodas y grupos como la Legión de María.</p>"},{"tipo":"cita","titulo":"","presentacion":{"estilo":"grande","alineacion":"centro","fondo":"oscuro"},"texto":"La Pasión de Jesús es la obra más grande y maravillosa del amor de Dios.","autor":"San Pablo de la Cruz","fuente":"Fundador de los Pasionistas"},{"tipo":"cronologia","titulo":"La parroquia en fechas","presentacion":{"disposicion":"cinta"},"hitos":[{"periodo":"1972","etiqueta":"Erección","titulo":"Nace la parroquia","relato":"En noviembre de 1972 el obispado erige la parroquia de Santa María Goretti y la encomienda a los Pasionistas, que acababan de llegar a Málaga.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"},{"periodo":"1973","etiqueta":"Río Baeza","titulo":"En unos bajos de la barriada","relato":"Todavía sin templo, la parroquia empieza a funcionar en unos locales de la calle Río Baeza. La inaugura el obispo Ángel Suquía el 3 de junio de 1973.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"},{"periodo":"1981","etiqueta":"El templo","titulo":"Una iglesia sin columnas","relato":"A finales de 1981 terminan las obras del templo, del arquitecto Verdú: una estructura triangular sin columnas, con forma de concha y lucernas circulares.\\n\\nLo bendice el obispo Ramón Buxarráis en diciembre de 1982.","foto":{"url":"","alt":"","pie":""},"tono":"oro"},{"periodo":"1997","etiqueta":"Retablo","titulo":"Un retablo nuevo","relato":"Se remodela el retablo y se incorpora nueva imaginería.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"},{"periodo":"2008","etiqueta":"Dedicación","titulo":"La dedicación del templo","relato":"Tras renovar en 2007 la cubierta, el suelo y la iluminación, el obispo Antonio Dorado Soto dedica solemnemente el templo el 12 de abril de 2008. La fecha se recuerda cada año.","foto":{"url":"","alt":"","pie":""},"tono":"granate"},{"periodo":"2011","etiqueta":"Imágenes","titulo":"San Gabriel y Santa María Goretti","relato":"Llegan al templo las imágenes de San Gabriel de la Dolorosa, santo pasionista, y de Santa María Goretti, titular de la parroquia.","foto":{"url":"","alt":"","pie":""},"tono":"ninguno"}]},{"tipo":"botones","titulo":"","presentacion":{"alineacion":"centro"},"botones":[{"texto":"Agenda de cultos","enlace":"/agenda","estilo":"principal"},{"texto":"Historia del Grupo","enlace":"/historia","estilo":"secundario"}]}]}'
WHERE `slug` = 'parroquia' AND `datos` LIKE '%Horarios y despacho%' AND `datos` LIKE '%cuadricula%';
